 async function refresh(){const {data}=await supabase.from("contacts").select("id,display_name,email,phone,linked_user_id,source_external_id,created_at").order("display_name"); if(data)setContacts(data as Contact[]);}
 async function addManual(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setMessage("");const form=new FormData(event.currentTarget);const {error}=await supabase.rpc("pantavion_add_manual_contact",{p_display_name:String(form.get("name")||"").trim()||null,p_email:String(form.get("email")||"").trim()||null,p_phone:String(form.get("phone")||"").trim()||null});setBusy(false);if(error)return setMessage(error.message);event.currentTarget.reset();await refresh();}
 async function importFile(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];if(!file)return;setBusy(true);setMessage("");try{const text=await file.text();const isVcard=file.name.toLowerCase().endsWith(".vcf");const parsed=isVcard?parseVCard(text):parseCsv(text);if(!parsed.length){setMessage("Δεν βρέθηκαν επαφές στο αρχείο.");return;}const {data,error}=await supabase.rpc("pantavion_import_contacts_batch",{p_source_type:isVcard?"vcard":"csv",p_filename:file.name,p_contacts:parsed});if(error){setMessage(error.message);return;}setMessage(`Μεταφέρθηκαν ${Number(data??0)} επαφές.`);event.target.value="";await refresh();}finally{setBusy(false);}}
 async function findMyPeople(){if(!contacts.length||busy)return;setBusy(true);setMessage("");setMatches([]);try{const response=await fetch("/api/people/find-from-contacts",{method:"POST"});const json=await response.json().catch(()=>({}));if(!response.ok){setMessage(json.detail||"Δεν ολοκληρώθηκε η αναζήτηση.");return;}const found=(json.matches??[]) as DiscoveryMatch[];setMatches(found);setMessage(found.length?`Βρέθηκαν ${found.length} επαφές που είναι ήδη στο Pantavion.`:"Δεν βρέθηκε ακόμη κάποια από αυτές τις επαφές στο Pantavion.");}finally{setBusy(false);}}
